SELECT (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients mp) AS total_male_patients, (SELECT COUNT(DISTINCT mpl.subject_id) FROM male_patients_68_78_with_intracranial_hemorrhage mpl) AS patients_with_intracranial_hemorrhage_68_78, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp) AS patients_with_intracranial_hemorrhage_73, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73 mp) AS patients_73, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_68_78 mp) AS patients_68_78, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_68_78_with_intracranial_hemorrhage mp) AS patients_with_intracranial_hemorrhage_68_78_and_73, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp) AS patients_with_intracranial_hemorrhage_73_and_78, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge')) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU')) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_before_transfer, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 10)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_after_transfer_and_discharged_within_30_days_and_stay_duration_less_than_10_days, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 20)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_after_transfer_and_discharged_within_30_days_and_stay_duration_less_than_20_days, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 20 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 30)) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_after_transfer_and_discharged_within_30_days_and_stay_duration_less_than_20_days_and_discharge_before_30_days, (SELECT COUNT(DISTINCT mp.subject_id) FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 20 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 30 AND (t.intime - t.outtime) <= 60) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_after_transfer_and_discharged_within_30_days_and_stay_duration_less_than_20_days_and_discharge_before_30_days_and_stay_duration_less_than_30_days FROM male_patients_73_with_intracranial_hemorrhage mp WHERE mp.subject_id IN (SELECT subject_id FROM transfers t WHERE t.transfer_id = 757071 AND t.eventtype = 'discharge' AND (t.intime - t.outtime) <= 30 AND t.careunit = 'ICU' AND t.intime > 757071 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 20 AND (t.intime - t.outtime) > 10 AND (t.intime - t.outtime) <= 30 AND (t.intime - t.outtime) > 30 AND (t.intime - t.outtime) <= 60) AS patients_with_intracranial_hemorrhage_73_and_78_and_transferred_and_discharged_within_30_days_in_icu_after_transfer_and_discharged_within_30_days_and_stay_duration_less_than_20_days_and_discharge_before_30_days_and_stay_duration_less_than_30_days;